using System.Linq.Expressions;using Microsoft.EntityFrameworkCore;using Npgsql;using ZosyalMedya.BuildingBlocks.Application.Persistence;using ZosyalMedya.Modules.Comments.Application.Ports;using ZosyalMedya.Modules.Comments.Domain.Comments;
namespace ZosyalMedya.Modules.Comments.Infrastructure.Persistence.PostgreSql;
public sealed class PostgreSqlCommentRepository(CommentsDbContext db):ICommentRepository{public async Task<Comment?>SelectAsync(Expression<Func<Comment,bool>>predicate,CancellationToken cancellationToken=default){var x=await db.Comments.AsNoTracking().Where(predicate).OrderBy(x=>x.Id).Take(2).ToListAsync(cancellationToken);return x.SingleOrDefault();}public async Task<IReadOnlyList<Comment>>ListByFilterAsync(Expression<Func<Comment,bool>>predicate,QueryOptions<Comment>?options=null,CancellationToken cancellationToken=default){options??=new();IQueryable<Comment>q=db.Comments.AsNoTracking().Where(predicate);IOrderedQueryable<Comment>?o=null;foreach(var s in options.Sort??[])o=o is null?(s.Direction==SortDirection.Ascending?q.OrderBy(s.KeySelector):q.OrderByDescending(s.KeySelector)):(s.Direction==SortDirection.Ascending?o.ThenBy(s.KeySelector):o.ThenByDescending(s.KeySelector));return await(o?.ThenBy(x=>x.Id)??q.OrderBy(x=>x.Id)).Take(options.BoundedLimit).ToListAsync(cancellationToken);}public async Task<IReadOnlyList<Comment>>ListPageAsync(CommentPageQuery query,CancellationToken cancellationToken=default){var limit=Math.Clamp(query.Limit,1,51);var contentId=query.ContentId.Value;var q=query.CursorTime.HasValue&&query.CursorId.HasValue?db.Comments.FromSqlInterpolated($"""SELECT * FROM comments.comments WHERE "ContentId" = {contentId} AND "Status" <> 'Moderated' AND ("CreatedAtUtc" > {query.CursorTime.Value} OR ("CreatedAtUtc" = {query.CursorTime.Value} AND "Id" > {query.CursorId.Value.Value})) ORDER BY "CreatedAtUtc" ASC, "Id" ASC LIMIT {limit}"""):db.Comments.FromSqlInterpolated($"""SELECT * FROM comments.comments WHERE "ContentId" = {contentId} AND "Status" <> 'Moderated' ORDER BY "CreatedAtUtc" ASC, "Id" ASC LIMIT {limit}""");return await q.AsNoTracking().ToListAsync(cancellationToken);}public async Task<CommentId>CreateAsync(Comment e,CancellationToken cancellationToken=default){try{db.Add(e);await db.SaveChangesAsync(cancellationToken);db.Entry(e).State=EntityState.Detached;return e.Id;}catch(DbUpdateException x)when(x.InnerException is PostgresException{SqlState:PostgresErrorCodes.UniqueViolation}){throw new PersistenceConflictException("comments.unique_conflict","Yorum zaten kayıtlıdır.",x);}}public async Task<bool>UpdateAsync(Expression<Func<Comment,bool>>predicate,Comment replacement,long?expectedVersion=null,CancellationToken cancellationToken=default){var q=db.Comments.Where(predicate);if(expectedVersion.HasValue)q=q.Where(x=>x.Version==expectedVersion);var c=await q.SingleOrDefaultAsync(cancellationToken);if(c is null)return false;db.Entry(c).CurrentValues.SetValues(replacement);try{return await db.SaveChangesAsync(cancellationToken)==1;}catch(DbUpdateConcurrencyException){return false;}finally{db.ChangeTracker.Clear();}}public async Task<long>DeleteByFilterAsync(Expression<Func<Comment,bool>>predicate,CancellationToken cancellationToken=default)=>await db.Comments.Where(predicate).ExecuteDeleteAsync(cancellationToken);public Task<long>CountVisibleAsync(CommentedContentId contentId,CancellationToken cancellationToken=default)=>db.Comments.LongCountAsync(x=>x.ContentId==contentId&&x.Status==CommentStatus.Visible,cancellationToken);}
